    row_band = row // 5 if row < 4 else ((row - 5) // 5 + 1) if row >= 5 and row < 10 else ((row - 10) // 5 + 2) if row >= 10 else ((row - 15) // 5 + 3) if row >= 15 else ((row - 20) // 5 + 4)

    # Simpler method
    if row <= 3:
        row_band = 0
    elif row <= 8:
        row_band = 1
    elif row <= 13:
        row_band = 2
    elif row <= 19:
        row_band = 3
    elif row <= 23:
        row_band = 4

    if col <= 3:
        col_band = 0
    elif col <= 8:
        col_band = 1
    elif col <= 13:
        col_band = 2
    elif col <= 19:
        col_band = 3
    elif col <= 23:
        col_band = 4

    return (row_band, col_band)

