def transform_fixed(grid):
    rows = len(grid)
    cols = len(grid[0])

    result = [[grid[r][c] for c in range(cols)] for r in range(rows)]  # Copy input

    # Now clear separator rows/cols, then add pattern
    # Actually, let's just copy the non-5 cells from input first
    # But easier: keep separators (5s) and clear the subgrid areas, then write pattern

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 5:
                continue  # Keep separator

    # Actually simpler: copy input, then modify subgrid cells
    result = [row[:] for row in grid]  # Deep copy

    # Clear colored cells in subgrids (keep separators 5)
    for r_start in range(0, rows - 3, 5):
        for c_start in range(0, cols - 3, 5):
            for r in range(4):
                for c in range(4):
                    if result[r_start + r][c_start + c] not in [0, 5]:
