    # Now apply the pattern for each colored subgrid
    for r_start in range(0, rows - 3, 5):
        for c_start in range(0, cols - 3, 5):
            colors = set()
            for r in range(4):
                for c in range(4):
                    val = grid[r_start + r][c_start + c]
                    if val not in [0, 5]:
                        colors.add(val)

            if not colors:
                continue

            color = list(colors)[0]
            PATTERN = [(0,1), (0,2), (1,2), (2,0), (2,1), (2,2), (2,3), (3,1)]
            for r_off, c_off in PATTERN:
