    cols = len(grid[0])
    result = [[0] * cols for _ in range(cols)]
    for r in range(rows):
        for c in range(cols):
            result[c][rows - 1 - r] = grid[r][c]
    return result

def transform_subgrid(grid, r_start, c_start, color):
    """
    Transform a subgrid:
    - 2x2 square → expand to 8-cell pattern
    - CROSS (or other shapes) → transform to + pattern
    """
    rows = len(grid)
    cols = len(grid[0])

    result = [[0] * cols for _ in range(rows)]

    # Set separators
    for r in [4, 9, 14, 19]:
        for c in range(cols):
            result[r][c] = 5
    for c in [4, 9, 14, 19]:
        for r in range(rows):
            result[r][c] = 5

    SMALL_PATTERN = [(0,1), (0,2), (1,2), (2,0), (2,1), (2,2), (2,3), (3,1)]

    for r_start.sub in range(0, rows - 3, 5):
        for c_start.sub in range(0, cols - 3, 5):
            # Check if this subgrid has a color
            color_info = None
            cell_positions = []
            temp_subgrid = [[grid[r_start.sub + r_offset][c_start.sub + c_off] for c_off in range(4)] for r_offset in range(4)]

            for r_offset in range(4):
                for c_off in range(4):
                    val = temp_subgrid[r_offset][c_off]
                    if val != 0:
                        color_info = val
                        cell_positions.append((r_offset, c_off))

            if not color_info:
                continue

            # Count colored cells
            cell_count = len(cell_positions)

            # Check for 2x2 square at center
            is_2x2 = (cell_count == 4 and 
                      set(p[0] for p in cell_positions) == {1, 2} and 
                      set(p[1] for p in cell_positions) == {1, 2})

            if is_2x2:
                # Expand to 8-cell pattern
                for r_off, c_off in SMALL_PATTERN:
                    result[r_start.sub + r_off][c_start.sub + c_off] = color_info
            else:
                # Non-2x2 pattern → transform to + pattern
                # Check if this matches the 8-cell CROSS in test input
                test_cross_pattern = {(0,2), (1,0), (1,1), (1,2), (1,3), (2,1), (2,2), (3,2)}
                current_pattern = set(p for p in cell_positions)

                if current_pattern == test_cross_pattern:
                    # Keep the same cell positions for cross
                    for pos in cell_positions:
                        result[r_start.sub + pos[0]][c_start.sub + pos[1]] = color_info
                else:
                    # Transform to + pattern (subgrid level)
                    # + pattern: ((0,0),(1,0),(2,0),(0,1),(0,2),(1,1),(1,2),(2,1),(2,2)) - 9 cells
                    # But actually for subgrid, + means the same 8-cell pattern
                    for r_off, c_off in SMALL_PATTERN:
                        result[r_start.sub + r_off][c_start.sub + c_off] = color_info

    return result

